from dsl import *


def build():
    # ============ Теория 1: аргументы ============
    terms1 = [
        ('позиционный аргумент', 'Аргумент, который передают просто значением. Какому параметру он достанется, определяет его место в списке: первый аргумент первому параметру, второй второму.\n\nПример:\ndef sub(a, b):\n    return a - b\nprint(sub(10, 3))\nВывод:\n7'),
        ('именованный аргумент', 'Аргумент, который передают с указанием имени параметра: имя=значение. Порядок таких аргументов не важен, а код становится понятнее.\n\nПример:\ndef sub(a, b):\n    return a - b\nprint(sub(b=3, a=10))\nВывод:\n7'),
        ('значение по умолчанию', 'Значение параметра, которое используется, если при вызове аргумент не передали. Записывается в объявлении: def f(x, k=1).\n\nПример:\ndef f(x, k=2):\n    return x * k\nprint(f(5))\nprint(f(5, 3))\nВывод:\n10\n15'),
        ('*args', 'Параметр со звёздочкой собирает все лишние позиционные аргументы в кортеж. Позволяет вызывать функцию с любым количеством значений.\n\nПример:\ndef total(*args):\n    return sum(args)\nprint(total(1, 2, 3))\nВывод:\n6'),
        ('**kwargs', 'Параметр с двумя звёздочками собирает все лишние именованные аргументы в словарь: ключи это имена, значения это переданные значения.\n\nПример:\ndef show(**kwargs):\n    print(kwargs)\nshow(a=1, b=2)\nВывод:\n{\'a\': 1, \'b\': 2}'),
        ('is', 'Оператор: проверяет, что слева и справа один и тот же объект. Для None принято писать именно is None, а не == None.\n\nПример:\nx = None\nprint(x is None)\nВывод:\nTrue'),
    ]
    body1 = '''
<p>В прошлой теме мы передавали в функцию значения просто по порядку. Такой способ называется позиционным, а сами значения [[позиционный аргумент|позиционными аргументами]]: что куда попадёт, определяет место. Напишем функцию, которая считает цену товара после скидки в процентах:</p>
''' + ex('''def final_price(price, discount):
    return price - price * discount / 100

print(final_price(1000, 5))''') + '''
<h3>Значения по умолчанию</h3>
<p>Часто функцию вызывают почти всегда с одним и тем же значением параметра. Тогда его записывают прямо в объявлении, и при вызове можно не указывать. Это [[значение по умолчанию|значение по умолчанию]]:</p>
''' + ex('''def final_price(price, discount=1):
    return price - price * discount / 100

print(final_price(1000, 5))
print(final_price(1000))''') + '''
<p>Скидка во втором вызове не передана, поэтому взята по умолчанию: 1%. Параметры со значениями по умолчанию должны стоять после обычных: <code>def f(a, b=1)</code> можно, а <code>def f(a=1, b)</code> нельзя.</p>

<h3>Ловушка: изменяемое значение по умолчанию</h3>
<p>Значение по умолчанию вычисляется <b>один раз</b>, в момент объявления функции, а не при каждом вызове. Если это число или строка, проблем нет. Но если это список, один и тот же список будет жить между вызовами:</p>
''' + ex('''def add_value(x, list_arg=[]):
    list_arg += [x]
    return list_arg

print(add_value(0))
print(add_value(0, [1, 2, 3]))
print(add_value(1))''') + '''
<p>Что произошло. Первый вызов дополнил пустой список по умолчанию и вернул <code>[0]</code>. Второй получил свой список, и всё как ожидалось. Третий снова взял список по умолчанию, но он уже помнит 0 из первого вызова, поэтому ответ <code>[0, 1]</code> вместо <code>[1]</code>.</p>
<p>Принятый способ избежать этого: в качестве значения по умолчанию ставят None, а новый список создают уже внутри функции. Проверка пишется через оператор [[is|is]], он отвечает на вопрос «это именно None?»:</p>
''' + ex('''def add_value(x, list_arg=None):
    if list_arg is None:
        list_arg = []
    list_arg += [x]
    return list_arg

print(add_value(0))
print(add_value(0, [1, 2, 3]))
print(add_value(1))''') + '''
<p>Теперь каждый вызов без списка получает собственный новый пустой список.</p>

<h3>Именованные аргументы</h3>
<p>Когда параметров много, легко перепутать их порядок. Чтобы вызов был понятнее, значение можно передать вместе с именем параметра. Это [[именованный аргумент|именованные аргументы]]. Их порядок не важен:</p>
''' + ex('''def final_price(price, discount=1):
    return price - price * discount / 100

print(final_price(1000, discount=5))
print(final_price(discount=10, price=1000))''') + '''
<p>Правило: <b>позиционные аргументы всегда идут первыми</b>, именованные после них. Python не сможет угадать порядок, если поменять их местами:</p>
''' + exs('''print(final_price(discount=5, 1000))''', '''SyntaxError: positional argument follows keyword argument''') + '''
<h3>Любое количество аргументов: *args</h3>
<p>Иногда заранее неизвестно, сколько значений передадут. Так работает print: ему можно дать сколько угодно аргументов. В своей функции для этого перед именем параметра ставят звёздочку (обычно имя args). Внутри функции [[*args|*args]] становится кортежем со всеми переданными значениями:</p>
''' + ex('''def show_all(*args):
    print(args)
    print(len(args))

show_all(10, 20, 30)
show_all()''') + '''
<p>Теперь можно переписать final_price так, чтобы она считала скидку для нескольких цен сразу. Параметр, стоящий после *prices, можно передавать только по имени:</p>
''' + ex('''def final_price(*prices, discount=1):
    return [price - price * discount / 100 for price in prices]

print(final_price(100, 200, 300, discount=5))''') + '''
<h3>Любые именованные аргументы: **kwargs</h3>
<p>Две звёздочки собирают все лишние именованные аргументы в словарь. Ключи словаря это имена, которые написал вызывающий, а значения это переданные значения. Обычное имя такого параметра kwargs (от keyword arguments), или [[**kwargs|**kwargs]]:</p>
''' + ex('''def show(**kwargs):
    print(kwargs)
    for name, value in kwargs.items():
        print(name, "=", value)

show(a=1, color="red")''') + '''
<p>С помощью kwargs можно сделать необязательные настройки. Например, пусть функция берёт только цены из заданного диапазона. Границы передаются под именами price_low и price_high, а если их нет, берутся наименьшая и наибольшая из цен. Метод словаря get возвращает запасное значение, если ключа нет:</p>
''' + ex('''def final_price(*prices, discount=1, **kwargs):
    low = kwargs.get("price_low", min(prices))
    high = kwargs.get("price_high", max(prices))
    return [price - price * discount / 100 for price in prices if low <= price <= high]

print(final_price(100, 200, 300, 400, 500, discount=5))
print(final_price(100, 200, 300, 400, 500, discount=5, price_low=200))
print(final_price(100, 200, 300, 400, 500, discount=5, price_high=200))
print(final_price(100, 200, 300, 400, 500, discount=5, price_low=200, price_high=350))''') + '''
<h3>Звёздочка при вызове</h3>
<p>Звёздочки работают и в обратную сторону. Если значения уже лежат в списке или словаре, их можно «распаковать» прямо в вызове: <code>*список</code> превращается в позиционные аргументы, <code>**словарь</code> в именованные.</p>
''' + ex('''def sub(a, b):
    return a - b

pair = [10, 3]
named = {"b": 3, "a": 10}
print(sub(*pair))
print(sub(**named))''') + '''
<p>Так делает и привычная запись <code>print(*items)</code>: она вызывает print, передав элементы списка отдельными аргументами.</p>
'''
    th1 = th('Позиционные и именованные аргументы', terms1, body1)

    fl1 = fl('Вопросы: аргументы', [
        qo('Что выведет программа?', '''def f(a, b=10):
    return a + b

print(f(1))''', ['11', '1', 'Ошибка'], 'Для b аргумент не передан, берётся значение по умолчанию 10. Результат 1 + 10 = 11.'),
        qo('Что выведет программа?', '''def f(a, b=10):
    return a + b

print(f(1, 2))''', ['3', '11', '12'], 'Если аргумент передан, значение по умолчанию не используется. b равно 2, результат 3.'),
        qo('Что выведет программа?', '''def f(a, b):
    return a - b

print(f(b=1, a=5))''', ['4', '-4', 'Ошибка'], 'Именованные аргументы можно передавать в любом порядке. a получает 5, b получает 1, и 5 - 1 = 4.'),
        qo('Что выведет программа?', '''def f(*args):
    return len(args)

print(f(5, 6, 7, 8))''', ['4', '1', '26'], 'Все четыре позиционных значения собираются в кортеж args. Его длина равна 4.'),
        qo('Что выведет программа?', '''def f(*args):
    return sum(args)

print(f())''', ['0', 'None', 'Ошибка'], 'Если аргументов нет, args это пустой кортеж. Сумма пустого кортежа равна 0.'),
        qo('Что выведет программа?', '''def f(**kwargs):
    return sorted(kwargs)

print(f(b=1, a=2))''', ["['a', 'b']", '[1, 2]', "['b', 'a']"], 'Параметр kwargs это словарь {"b": 1, "a": 2}. Функция sorted по словарю берёт его ключи и сортирует: a, b.'),
        qo('Что выведет программа?', '''def f(x, items=[]):
    items.append(x)
    return len(items)

f(1)
f(2)
print(f(3))''', ['3', '1', 'Ошибка'], 'Список по умолчанию создаётся один раз. Все три вызова добавляют элементы в один и тот же список, поэтому после третьего его длина равна 3.'),
        qo('Что выведет программа?', '''def f(x, items=None):
    if items is None:
        items = []
    items.append(x)
    return len(items)

f(1)
f(2)
print(f(3))''', ['1', '3', 'Ошибка'], 'Теперь при каждом вызове без списка создаётся новый пустой список. После третьего вызова в нём лежит только одно значение.'),
        qo('Что выведет программа?', '''def f(a, b, c):
    return a * 100 + b * 10 + c

nums = [1, 2, 3]
print(f(*nums))''', ['123', '6', 'Ошибка'], 'Запись *nums передаёт элементы списка как три отдельных аргумента: a = 1, b = 2, c = 3. Результат 100 + 20 + 3 = 123.'),
        q('Какая запись объявления функции неверна?', 'def f(a=1, b):', ['def f(a, b=1):', 'def f(a, b=1, c=2):', 'def f(a, *args):'], 'Параметры со значением по умолчанию должны стоять после обычных, иначе Python не поймёт, какие аргументы можно пропустить.'),
        q('Какая запись вызова неверна?', 'f(a=1, 2)', ['f(1, b=2)', 'f(1, 2)', 'f(b=2, a=1)'], 'Именованный аргумент нельзя ставить раньше позиционного: после него Python уже не угадает, куда девать позиционные значения.'),
        q('Что собирает в себя параметр **kwargs?', 'Лишние именованные аргументы, в виде словаря', ['Лишние позиционные аргументы, в виде кортежа', 'Все аргументы сразу, в виде списка', 'Только числа, в виде множества'], 'Две звёздочки означают «все лишние именованные аргументы». Python складывает их в словарь: имя аргумента станет ключом.'),
    ])

    # ============ Теория 2: функции высшего порядка и lambda ============
    terms2 = [
        ('функция высшего порядка', 'Функция, которая принимает другую функцию как аргумент или возвращает функцию. Примеры: map, filter, sorted с параметром key.\n\nПример:\ndef apply(f, x):\n    return f(x)\nprint(apply(abs, -5))\nВывод:\n5'),
        ('filter', 'Функция: принимает функцию-условие и набор значений. Оставляет только те значения, для которых условие вернуло истину. Результат это итератор, его превращают в список или перебирают циклом.\n\nПример:\nprint(list(filter(str.isdigit, "a1b2")))\nВывод:\n[\'1\', \'2\']'),
        ('map', 'Функция: применяет функцию к каждому элементу набора. Результат это итератор, его превращают в список или перебирают циклом.\n\nПример:\nprint(list(map(len, ["аб", "в"])))\nВывод:\n[2, 1]'),
        ('lambda', 'Ключевое слово: создаёт маленькую безымянную функцию одним выражением. После двоеточия записывают то, что функция вернёт, слово return не нужно.\n\nПример:\nf = lambda x: x + 1\nprint(f(4))\nВывод:\n5'),
        ('reduce', 'Функция из модуля functools: «сворачивает» набор значений в одно. Берёт первые два, применяет функцию, потом результат и третье значение, и так до конца.\n\nПример:\nfrom functools import reduce\nprint(reduce(lambda a, b: a * b, [1, 2, 3, 4]))\nВывод:\n24'),
        ('итератор', 'Объект, который выдаёт значения по одному и только один раз. Его можно перебрать циклом или превратить в список. Вторично перебрать уже нельзя.\n\nПример:\nit = map(abs, [-1, -2])\nprint(list(it))\nprint(list(it))\nВывод:\n[1, 2]\n[]'),
    ]
    body2 = '''
<p>Функции в Python это такие же значения, как числа и строки. Их можно присваивать переменным, хранить в списках и словарях и передавать в другие функции. Важно различать два вида записи: <code>double(4)</code> вызывает функцию и даёт результат, а <code>double</code> без скобок это сама функция как объект.</p>
''' + ex('''def double(x):
    return x * 2

f = double
print(f(4))
print(type(double))

ops = {"двойное": double, "минус": abs}
print(ops["двойное"](5))

def apply(func, x):
    return func(x)

print(apply(double, 7))
print(apply(abs, -7))''') + '''
<p>Функция <code>apply</code> принимает другую функцию в параметре func и вызывает её. Такие функции называют [[функция высшего порядка|функциями высшего порядка]]. Вызов переданной функции «позже и при выполнении условий» ещё называют обратным вызовом (callback): мы даём функции инструмент, а она сама решает, когда его применить.</p>

<h3>filter: отобрать нужное</h3>
<p>Функция [[filter|filter]] получает функцию-условие и набор значений. Условие должно вернуть True или False. В результат попадают только те значения, для которых вернулось True:</p>
''' + ex('''def only_pos(x):
    return x > 0

result = filter(only_pos, [-1, 5, 6, -10, 0])
print(type(result))
print(list(result))''') + '''
<p>Первая печать показывает, что filter возвращает не список, а особый объект, [[итератор|итератор]]. Он выдаёт значения по одному и только один раз, поэтому его превращают в список или перебирают циклом. В filter можно передавать и готовые функции и методы, например <code>str.isalpha</code>:</p>
''' + ex('''print("".join(filter(str.isalpha, "123ABcd()")))''') + '''
<h3>map: преобразовать каждый элемент</h3>
<p>Функция [[map|map]] применяет функцию к каждому элементу набора и тоже возвращает итератор:</p>
''' + ex('''def square(x):
    return x ** 2

print(list(map(square, range(5))))
print(list(map(str.lower, ["abCD", "EFGh"])))''') + '''
<p>Самое частое применение: превратить введённую строку чисел в список. Вот что делает строка <code>numbers = list(map(int, input().split()))</code>: читает строку, режет её по пробелам, превращает каждую часть в int и собирает в список:</p>
''' + ex('''numbers = list(map(int, input().split()))
print(numbers)
print(sum(numbers))''', ['4 10 7']) + '''
<h3>lambda: функция «на месте»</h3>
<p>Для маленьких функций, которые нужны один раз, отдельное def неудобно. Вместо него пишут [[lambda|lambda-функцию]]: слово lambda, параметры, двоеточие и выражение, которое будет результатом. Слова return здесь нет, оно подразумевается.</p>
''' + ex('''print(list(filter(lambda x: x > 0, [-1, 5, 6, -10, 0])))
print(list(map(lambda x: x ** 2, range(5))))

add = lambda a, b: a + b
print(add(2, 3))''') + '''
<p>Лямбду можно присвоить имени, как в последних двух строках, но для функции с именем лучше писать def: так в сообщениях об ошибках видно имя. Настоящая сила lambda в том, чтобы вставить маленькое правило прямо туда, где его требует другая функция.</p>

<h3>lambda в sorted, min и max</h3>
<p>Функции sorted, min, max и метод sort принимают параметр key: функцию, которая для каждого элемента считает «ключ» для сравнения. Если вернуть из лямбды кортеж, сравнивать будут по нескольким признакам: сначала по первому элементу, при равенстве по второму и так далее. Минус перед числом даёт обратный порядок.</p>
''' + ex('''lines = ["abcd", "ab", "ba", "acde"]
print(sorted(lines, key=lambda line: len(line)))
print(sorted(lines, key=lambda line: (len(line), line)))
print(sorted(lines, key=lambda line: (-len(line), line)))
print(min(lines, key=lambda line: (-len(line), line)))''') + '''
<h3>Генераторное выражение вместо map и filter</h3>
<p>То же самое, что делают map и filter, часто проще записать выражением с for и if. Многим такая запись читается легче, что лучше, дело вкуса:</p>
''' + ex('''numbers = [-1, 5, 6, -10, 0]
print([x ** 2 for x in numbers if x > 0])
print(list(map(lambda x: x ** 2, filter(lambda x: x > 0, numbers))))''') + '''
<h3>reduce: свернуть всё в одно значение</h3>
<p>Функция [[reduce|reduce]] из модуля functools берёт функцию двух аргументов и «накапливает» результат: сначала применяет её к первым двум элементам, потом к полученному значению и третьему, и так до конца. Сумма чисел от 1 до 5: <code>(((1 + 2) + 3) + 4) + 5</code>.</p>
''' + ex('''from functools import reduce

numbers = range(1, 6)
print(reduce(lambda x, y: x + y, numbers))
print(reduce(lambda x, y: x * y, numbers))
print(reduce(lambda a, b: a + "-" + b, ["а", "б", "в"]))''') + '''
<p>Так можно сворачивать не только числа: произведение, склейку строк, поиск минимума. Хорошо подходит и для «накопления» с функцией от двух значений, например наибольшего общего делителя: <code>reduce(gcd, numbers)</code>, если gcd умеет работать с парой чисел.</p>
'''
    th2 = th('Функции высшего порядка и lambda', terms2, body2)

    fl2 = fl('Вопросы: map, filter, lambda', [
        qo('Что выведет программа?', '''print(list(map(lambda x: x + 1, [1, 2, 3])))''', ['[2, 3, 4]', '[1, 2, 3]', '[3, 4, 5]'], 'map применяет лямбду к каждому элементу: 1 + 1, 2 + 1, 3 + 1. Результат превращён в список функцией list.'),
        qo('Что выведет программа?', '''print(list(filter(lambda x: x % 2 == 0, range(7))))''', ['[0, 2, 4, 6]', '[1, 3, 5]', '[2, 4, 6]'], 'Чётные числа из 0, 1, ..., 6 это 0, 2, 4, 6. Ноль чётный, остаток от деления на 2 равен 0.'),
        qo('Что выведет программа?', '''print(max(["кот", "слон", "ёж"], key=lambda s: len(s)))''', ['слон', 'ёж', 'кот'], 'Максимум ищется по длине слова: у слова «слон» длина 4, больше, чем у остальных.'),
        qo('Что выведет программа?', '''words = ["bb", "a", "ccc", "dd"]
print(sorted(words, key=lambda w: (-len(w), w)))''', ["['ccc', 'bb', 'dd', 'a']", "['a', 'bb', 'dd', 'ccc']", "['ccc', 'dd', 'bb', 'a']"], 'Сначала сравнивается -len(w): самые длинные слова идут первыми. Для слов одинаковой длины (bb и dd) решает вторая часть кортежа, то есть алфавит.'),
        qo('Что выведет программа?', '''from functools import reduce
print(reduce(lambda a, b: a - b, [10, 3, 2]))''', ['5', '9', '-5'], 'Сначала 10 - 3 = 7, потом 7 - 2 = 5. Reduce идёт слева направо.'),
        qo('Что выведет программа?', '''f = lambda x, y: x * y + 1
print(f(3, 4))''', ['13', '12', '8'], 'Лямбда вернёт результат выражения: 3 * 4 + 1 = 13.'),
        qo('Что выведет программа?', '''numbers = map(int, "1 2 3".split())
print(sum(numbers) + sum(numbers))''', ['6', '12', '0'], 'Итератор map одноразовый. Первый sum забирает все три значения, а второй получает уже пустой итератор и возвращает 0. Итого 6 + 0.'),
        qo('Что выведет программа?', '''def apply(func, x):
    return func(func(x))

print(apply(lambda n: n * 3, 2))''', ['18', '12', '6'], 'Функция применяется дважды: сначала 2 * 3 = 6, потом 6 * 3 = 18.'),
        q('Что вернёт filter(функция, список)?', 'Итератор с теми элементами, для которых функция вернула True', ['Новый список с теми элементами', 'Число подходящих элементов', 'Первый подходящий элемент'], 'Результат filter это итератор, а не список. Его нужно превратить в список функцией list или перебрать циклом.'),
        q('Чем отличаются double и double(4)?', 'double это функция, double(4) её результат', ['Ничем, это одно и то же', 'double это число, double(4) функция', 'double(4) ошибка, скобки не нужны'], 'Без скобок мы работаем с самой функцией, например передаём её в другую функцию. Со скобками функция вызывается, и получается результат.'),
    ])

    # ============ Задания ============
    t1 = task('Напиши функцию month(number, language="ru"): она принимает номер месяца от 1 до 12 и язык ("ru" по умолчанию или "en") и возвращает название месяца с заглавной буквы. Русские названия: Январь, Февраль, Март, Апрель, Май, Июнь, Июль, Август, Сентябрь, Октябрь, Ноябрь, Декабрь. Английские: January, February, March, April, May, June, July, August, September, October, November, December.',
              'Храни названия в двух списках (по одному на язык) и выбирай нужный по параметру language. Номер месяца начинается с 1, а индексы списка с 0, поэтому берётся элемент number - 1. Значение "ru" задай в объявлении: def month(number, language="ru").',
              'def month(number, language="ru"):\n    ru = ["Январь", "Февраль", "Март", "Апрель", "Май", "Июнь", "Июль", "Август", "Сентябрь", "Октябрь", "Ноябрь", "Декабрь"]\n    en = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]\n    names = en if language == "en" else ru\n    return names[number - 1]',
              ['print(month(1, "en"))', 'print(month(7))', 'print(month(12, "ru"))', 'print(month(5, "en"))', 'print(month(3))'], tail=TL)

    t2 = task('Напиши функцию make_matrix(size, value=0): она создаёт и возвращает матрицу (список списков). Параметр size это либо кортеж (ширина, высота), либо одно число для квадратной матрицы. Параметр value это значение всех клеток (по умолчанию 0). Матрица (4, 2) состоит из двух строк по четыре элемента.',
              'Определи ширину и высоту: если isinstance(size, tuple), то n, m = size, иначе n = m = size. Построй список списков выражением: [[value for _ in range(n)] for _ in range(m)]. Не пиши [[value] * n] * m: так все строки окажутся одним и тем же списком.',
              'def make_matrix(size, value=0):\n    if isinstance(size, tuple):\n        n, m = size\n    else:\n        n = m = size\n    return [[value for _ in range(n)] for _ in range(m)]',
              ['print(make_matrix(3))', 'print(make_matrix((4, 2), 1))', 'print(make_matrix((1, 3), "x"))', 'm = make_matrix(2)\nm[0][0] = 5\nprint(m)'], tail=TL)

    t3 = task('Напиши функцию gcd(*numbers): она принимает любое количество натуральных чисел (не меньше одного) и возвращает их наибольший общий делитель. Для одного числа результат это само число.',
              'Параметр *numbers станет кортежем. Наибольший общий делитель двух чисел находят алгоритмом Евклида: пока b не равно 0, делай a, b = b, a % b. Для многих чисел применяй его по цепочке: reduce(gcd2, numbers), где gcd2 твоя вспомогательная функция для пары. Либо возьми готовый math.gcd.',
              'from functools import reduce\n\n\ndef gcd2(a, b):\n    while b:\n        a, b = b, a % b\n    return a\n\n\ndef gcd(*numbers):\n    return reduce(gcd2, numbers)',
              ['print(gcd(3))', 'print(gcd(36, 48, 156, 100500))', 'print(gcd(7, 13))', 'print(gcd(100, 75))', 'print(gcd(12, 12, 12))'], tail=TL)

    t4 = task('Напиши функцию get_operator(operator): она принимает строку с обозначением одной из операций (+, -, *, //, **) и возвращает функцию двух аргументов, которая выполняет эту операцию. Например, get_operator("+")(3, 5) равно 8.',
              'Функции можно хранить в словаре. Заведи словарь, где ключ это строка с операцией, а значение это лямбда: {"+": lambda a, b: a + b, "-": lambda a, b: a - b, ...}. Верни найденную функцию: return ops[operator]. Скобки после ops[operator] не ставь: нужна сама функция, а не её результат.',
              'def get_operator(operator):\n    ops = {"+": lambda a, b: a + b, "-": lambda a, b: a - b, "*": lambda a, b: a * b, "//": lambda a, b: a // b, "**": lambda a, b: a ** b}\n    return ops[operator]',
              ['op = get_operator("+")\nprint(op(3, 5))', 'op = get_operator("**")\nprint(op(2, 10))', 'print(get_operator("-")(10, 4))', 'print(get_operator("//")(17, 5))', 'print(get_operator("*")(6, 7))'], tail=TL)

    t5 = task('Запиши lambda-выражение для отбора чисел с чётной суммой цифр и присвой его переменной f (строка должна начинаться с f = lambda). Проверка применит её так: print(*filter(f, (1, 2, 3, 4, 5))).',
              'У лямбды один параметр, пусть n. Сумму цифр числа получают так: sum(map(int, str(n))). Она чётная, когда остаток от деления на 2 равен 0. Осталось записать f = lambda n: ... % 2 == 0.',
              'f = lambda n: sum(map(int, str(n))) % 2 == 0',
              ['print(*filter(f, (1, 2, 3, 4, 5)))', 'print(*filter(f, (32, 64, 128, 256, 512)))', 'print(*filter(f, (11, 20, 101, 99)))', 'print(*filter(f, range(10, 20)))'], tail=TL)

    t6 = task('Запиши lambda-выражение, которое преобразует пару (ключ, значение) из словаря, и присвой его переменной f (f = lambda ...). Ключ нужно записать в нижнем регистре, удалив цифры, пробелы и знаки препинания (оставить только буквы). Если значение итерируемое (список или кортеж), его нужно заменить суммой элементов, иначе оставить как есть. Проверка запустит: print(dict(map(f, {...}.items()))).',
              'Лямбда получает один кортеж, назовём его kv, тогда ключ это kv[0], значение kv[1]. Верни кортеж из двух частей: "".join(filter(str.isalpha, kv[0])).lower() и значение (sum(kv[1]) if isinstance(kv[1], (list, tuple)) else kv[1]). Условное выражение a if условие else b вполне помещается в лямбду.',
              'f = lambda kv: ("".join(filter(str.isalpha, kv[0])).lower(), sum(kv[1]) if isinstance(kv[1], (list, tuple)) else kv[1])',
              ["print(dict(map(f, {'First 1': 2, 'second:': (2, 1, 1), 'THIRD': [1, 2, 3]}.items())))", "print(dict(map(f, {'A-1': [10, 20], 'b b': 5}.items())))", "print(dict(map(f, {'X': (1,)}.items())))"], tail=TL)

    t7 = task('Напиши функцию login(name, password, success, error): она проверяет пароль и вызывает один из двух обратных вызовов (функции, принимающие имя). Алгоритм: сложи коды всех символов имени (ord), умножь на длину имени и переведи результат в 16-ричную систему (без префикса 0x). Полученная строка, записанная задом наперёд, должна совпасть с паролем без учёта регистра. Если совпала, вызови success(name), иначе error(name).',
              'Сумма кодов: sum(map(ord, name)). Умножь на len(name). 16-ричная запись: f"{число:x}" (без префикса 0x). Переверни строку срезом [::-1]. Сравнивай оба значения в нижнем регистре: code[::-1].lower() == password.lower(). Дальше обычное if/else, где вызываются success(name) или error(name).',
              'def login(name, password, success, error):\n    code = f"{sum(map(ord, name)) * len(name):x}"\n    if code[::-1].lower() == password.lower():\n        success(name)\n    else:\n        error(name)',
              ['def on_login(username):\n    print(f"Hello, {username}!")\n\n\ndef on_fail(username):\n    print(f"Nice try... You are not {username}!")\n\n\nlogin("NoobMaster", "4C72", on_login, on_fail)',
               'def hello(username):\n    print(f"Здравствуйте, {username}!")\n\n\ndef alert(username):\n    print(f"Попытка взлома {username}")\n\n\nlogin("оченьМаленькийРозовыйПони", "EDE5A", hello, alert)',
               'def ok(n):\n    print("ok", n)\n\n\ndef bad(n):\n    print("bad", n)\n\n\nlogin("Max", "1234", ok, bad)'], tail=TL)

    t8 = task('Напиши функцию choice(*args, **kwargs): она принимает любое количество целых чисел и ровно один именованный параметр: min или max, значением которого служит функция. Если передан min, верни наименьший из результатов применения этой функции ко всем числам. Если max, верни наибольший.',
              'Имена min и max нельзя сделать параметрами, это встроенные функции, но в kwargs они лежат как ключи словаря. Определи, какой параметр передан: if "min" in kwargs: f = kwargs["min"]; g = min, иначе f = kwargs["max"]; g = max. Тогда ответ это g(map(f, args)).',
              'def choice(*args, **kwargs):\n    if "min" in kwargs:\n        f = kwargs["min"]\n        g = min\n    else:\n        f = kwargs["max"]\n        g = max\n    return g(map(f, args))',
              ['print(choice(1, 2, 3, 4, 5, max=lambda x: 2 ** x))', 'print(choice(321, 87, 1000, -23, min=lambda x: len(str(x))))', 'print(choice(3, -7, 5, min=abs))', 'print(choice(3, -7, 5, max=lambda x: -x))'], tail=TL)

    t9 = task('Напиши функцию grow(*args, **kwargs): она принимает любое количество чисел и любое количество именованных параметров. Каждое число нужно увеличить на значение каждого именованного параметра, у которого длина названия делит это число нацело (число кратно длине названия). Проверять надо исходное число. Верни кортеж преобразованных чисел. Пример: grow(1, 2, 3, 4, 5, ab=7, dad=10) вернёт (1, 9, 13, 11, 5).',
              'Пройди по числам args, для каждого заведи result = число. Затем перебери kwargs.items(): если число % len(имя) == 0, добавь значение к result. Условие проверяй по исходному числу, а не по result. Собранные значения складывай в список и в конце верни tuple(список).',
              'def grow(*args, **kwargs):\n    out = []\n    for x in args:\n        result = x\n        for name, value in kwargs.items():\n            if x % len(name) == 0:\n                result += value\n        out.append(result)\n    return tuple(out)',
              ['print(grow(1, 2, 3, 4, 5, ab=7, dad=10))', 'print(grow(12, 5, 30, 60, 15, first=13, second=2, Bob=7))', 'print(grow(4, 8))', 'print(grow(10, 20, z=1))'], tail=TL,
              exp={'print(grow(1, 2, 3, 4, 5, ab=7, dad=10))': '(1, 9, 13, 11, 5)', 'print(grow(12, 5, 30, 60, 15, first=13, second=2, Bob=7))': '(21, 18, 52, 82, 35)'})

    t10 = task('Вася шифрует сообщения заменой символов. Напиши функцию secret_replace(text, **rules): text это исходный текст, а каждое именованное правило имеет вид символ=кортеж_замен. Правила применяются по очереди, в порядке записи. Внутри правила замены идут по одной: первое вхождение символа заменяется на первый элемент кортежа, второе на второй, и так по кругу. Функция возвращает зашифрованный текст. Регистр важен. Пример: secret_replace("aaa", a=("x", "y")) вернёт "xyx".',
               'Для каждого правила (символ, кортеж) разрежь текущий текст по символу: parts = text.split(символ). Первая часть остаётся как есть, а после каждой следующей вставляется замена номер i % len(кортеж): собери result = parts[0], затем в цикле result += замены[i % len(замены)] + part. Результат сохрани как новый text и переходи к следующему правилу.',
               'def secret_replace(text, **rules):\n    for key, vals in rules.items():\n        parts = text.split(key)\n        result = parts[0]\n        for i, part in enumerate(parts[1:]):\n            result += vals[i % len(vals)] + part\n        text = result\n    return text',
               ['print(secret_replace("Hello, world!", l=("hi", "y"), o=("123", "z")))', 'print(secret_replace("ABRA-KADABRA", A=("Z", "1", "!"), B=("3",), R=("X", "7"), K=("G", "H"), D=("0", "2")))', 'print(secret_replace("aaa", a=("x", "y")))', 'print(secret_replace("без правил"))'], tail=TL,
               exp={'print(secret_replace("Hello, world!", l=("hi", "y"), o=("123", "z")))': 'Hehiy123, wzrhid!', 'print(secret_replace("ABRA-KADABRA", A=("Z", "1", "!"), B=("3",), R=("X", "7"), K=("G", "H"), D=("0", "2")))': 'Z3X1-G!0Z371'})

    t11 = task('Лаборанты собирают пары рациональных чисел. Напиши три функции: enter_results(*args) добавляет результаты (числа идут парами: первое, второе, первое, второе, ..., количество чётное); get_sum() возвращает кортеж из двух сумм (сумма первых чисел, сумма вторых); get_average() возвращает кортеж средних арифметических (первых и вторых). Все числа округляются до сотых функцией round(x, 2). Если данных нет, обе функции возвращают (0.0, 0.0). Данные хранятся между вызовами функций.',
               'Данные нужно помнить между вызовами, значит, нужна глобальная переменная вне функций: DATA = [] со списком пар. Изменять список через append можно без слова global. В enter_results возьми args[::2] (первые) и args[1::2] (вторые) и добавляй пары: for a, b in zip(args[::2], args[1::2]): DATA.append((a, b)). Для сумм пройди по DATA. Для средних раздели суммы на len(DATA). Не забудь случай, когда DATA пуст.',
               'DATA = []\n\n\ndef enter_results(*args):\n    for a, b in zip(args[::2], args[1::2]):\n        DATA.append((a, b))\n\n\ndef get_sum():\n    if not DATA:\n        return (0.0, 0.0)\n    return (round(sum(a for a, b in DATA), 2), round(sum(b for a, b in DATA), 2))\n\n\ndef get_average():\n    if not DATA:\n        return (0.0, 0.0)\n    s = get_sum()\n    return (round(s[0] / len(DATA), 2), round(s[1] / len(DATA), 2))',
               ['enter_results(1, 2, 3, 4, 5, 6)\nprint(get_sum(), get_average())\nenter_results(1, 2)\nprint(get_sum(), get_average())',
                'enter_results(3.5, 2.14, 45.2, 37.99)\nprint(get_sum(), get_average())\nenter_results(5.2, 7.3)\nprint(get_sum(), get_average())\nenter_results(1.23, 4.56, 3.14, 2.71, 0, 0)\nprint(get_sum(), get_average())',
                'print(get_sum(), get_average())'], tail=TL,
               exp={'enter_results(1, 2, 3, 4, 5, 6)\nprint(get_sum(), get_average())\nenter_results(1, 2)\nprint(get_sum(), get_average())': '(9, 12) (3.0, 4.0)\n(10, 14) (2.5, 3.5)',
                    'enter_results(3.5, 2.14, 45.2, 37.99)\nprint(get_sum(), get_average())\nenter_results(5.2, 7.3)\nprint(get_sum(), get_average())\nenter_results(1.23, 4.56, 3.14, 2.71, 0, 0)\nprint(get_sum(), get_average())': '(48.7, 40.13) (24.35, 20.07)\n(53.9, 47.43) (17.97, 15.81)\n(58.27, 54.7) (9.71, 9.12)'})

    t12 = task('Сделай мини-базу данных из двух функций. insert(*users) добавляет одного или нескольких пользователей: каждый это словарь с ключами id (натуральное число), name (строка) и birth (дата в формате ДД.ММ.ГГГГ). select(*conditions) возвращает список словарей пользователей, отсортированный по возрастанию id. Без аргументов возвращает всех, а с условиями только тех, кто подходит под все условия сразу. Условие это строка вида «поле оператор значение» через пробелы, операторы: <, <=, >, >=, ==, !=. Числа сравниваются как числа, имена как строки, даты как даты.',
               'Храни пользователей в глобальном списке DB. Словарь операторов: ops = {"<": lambda a, b: a < b, ">": ..., "==": ...}. Условие разбей методом split(): field, op, value = cond.split(). Перед сравнением приведи значение к нужному типу: для id это int, для birth это datetime.strptime(текст, "%d.%m.%Y"), для name строка как есть. Удобно написать маленькую функцию conv(field, text), которая возвращает преобразованное значение. Отбери подходящих через all(...) по всем условиям, затем отсортируй по ключу lambda u: u["id"].',
               'from datetime import datetime\n\nDB = []\nOPS = {"<": lambda a, b: a < b, "<=": lambda a, b: a <= b, ">": lambda a, b: a > b, ">=": lambda a, b: a >= b, "==": lambda a, b: a == b, "!=": lambda a, b: a != b}\n\n\ndef conv(field, text):\n    if field == "id":\n        return int(text)\n    if field == "birth":\n        return datetime.strptime(text, "%d.%m.%Y")\n    return text\n\n\ndef insert(*users):\n    DB.extend(users)\n\n\ndef select(*conditions):\n    result = []\n    for user in DB:\n        ok = True\n        for cond in conditions:\n            field, op, value = cond.split()\n            if not OPS[op](conv(field, str(user[field])), conv(field, value)):\n                ok = False\n        if ok:\n            result.append(user)\n    return sorted(result, key=lambda u: u["id"])',
               ["insert({'id': 1, 'name': 'Ann', 'birth': '01.03.2001'})\ninsert({'id': 3, 'name': 'Bob', 'birth': '05.03.2002'}, {'id': 4, 'name': 'Chuck', 'birth': '07.06.2001'})\nprint([u['name'] for u in select()])\nprint([u['name'] for u in select('name > B')])\ninsert({'id': 2, 'name': 'Den', 'birth': '29.02.2000'})\nprint([u['name'] for u in select('name > B')])\nprint([u['name'] for u in select('id <= 2')])\nprint(*select('birth >= 12.04.2001'), sep='\\n')",
                "insert({'id': 10, 'name': 'Zed', 'birth': '01.01.1999'}, {'id': 9, 'name': 'Yan', 'birth': '31.12.1999'})\nprint([u['id'] for u in select()])\nprint([u['id'] for u in select('birth > 31.12.1999')])\nprint([u['name'] for u in select('id >= 9', 'name != Zed')])",
                "print(select())\ninsert({'id': 5, 'name': 'Eva', 'birth': '10.10.2010'})\nprint(select('id == 5'))\nprint(select('id == 6'))"], tail=TL)

    ts1 = ts('Задания: аргументы, lambda', [t1, t2, t3, t4, t5, t6, t7, t8, t9, t10, t11, t12])

    return topic('Аргументы, высшие функции и lambda', 'именованные аргументы, *args, **kwargs, map, filter, lambda, reduce', [th1, fl1, th2, fl2, ts1])
